 def test_search_continues_after_full_page_and_deduplicates_between_pages() -> None:
     starts = []

     def handler(request):
         if request.url.path.endswith("/products/"):
             return httpx.Response(200, text="")
         starts.append(request.url.params["start"])
         if starts[-1] == "1":
